#include <Arduino.h>

const byte leds[3] = {2,3,4};
const byte buttons[3] = {5,6,7};
enum Mode { CYCLING, HOLD, OFF };
Mode mode = CYCLING;
byte color = 0;
bool previous[3] = {HIGH,HIGH,HIGH};
unsigned long started = 0;
unsigned long elapsedHeld = 0;

void render() {
  for (byte i=0;i<3;i++) digitalWrite(leds[i], mode != OFF && i == color ? HIGH : LOW);
}

void setup() {
  for (byte i=0;i<3;i++) {
    pinMode(leds[i], OUTPUT);
    pinMode(buttons[i], INPUT_PULLUP);
  }
  started = millis();
  render();
}

void loop() {
  unsigned long now = millis();
  if (mode == CYCLING) {
    while (now - started >= 2000UL) {
      started += 2000UL;
      color = (color + 1) % 3;
    }
  }
  for (byte i=0;i<3;i++) {
    bool level = digitalRead(buttons[i]);
    if (previous[i] == HIGH && level == LOW) {
      if (i == 0 && mode == CYCLING) {
        elapsedHeld = now - started;
        mode = HOLD;
      } else if (i == 1 && mode != CYCLING) {
        started = now - elapsedHeld;
        mode = CYCLING;
      } else if (i == 2) {
        if (mode == CYCLING) elapsedHeld = now - started;
        mode = OFF;
      }
    }
    previous[i] = level;
  }
  render();
}
